('00000000-0000-0000-0000-000000000201', 'BAND_PULL_APART', 'Resistance Band Pull-Apart', 'Hold the band at shoulder height, keep your ribs down and pull your hands apart until the band reaches your chest.', 'Upper back', 'Resistance bands', FALSE, TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('00000000-0000-0000-0000-000000000202', 'BANDED_GLUTE_WALK', 'Banded Lateral Walk', 'Keep steady tension on the band and take controlled side steps without letting your knees collapse inward.', 'Lower body', 'Resistance bands', FALSE, TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
