('00000000-0000-0000-0000-000000000209', 'MEDICINE_BALL_SLAM', 'Medicine Ball Slam', 'Reach tall, brace your trunk and drive the ball toward the floor with your whole body.', 'Conditioning', 'Medicine ball', FALSE, TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
('00000000-0000-0000-0000-000000000210', 'ASSISTED_PULL_UP', 'Assisted Pull-Up', 'Start from a stable hang, pull your chest toward the bar and lower under control.', 'Back', 'Pull-up bar', FALSE, TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0),
